/**
 * Fast-lane test config: the default `pnpm run test` inventory minus the
 * static slow list (scripts/test-slow-manifest.txt, one repo-relative spec
 * path per line, threshold = single-file measured duration > 2s).
 *
 * The exclusion is file-exact rather than a duration guess at run time: the
 * list is generated by scripts/test-duration-profile.mjs from a full-suite
 * log and kept dangling-free by its `--check` mode, so this config only has
 * to subtract it. The full suite stays one keystroke away behind
 * `pnpm run test:all`, which runs this repo's stock vitest.config.ts.
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import base from './vitest.config.ts'
import { defineConfig } from 'vitest/config'

const manifestUrl = new URL('./scripts/test-slow-manifest.txt', import.meta.url)

/** Exclusions for every project lane: the manifest is lane-agnostic. */
const slowSpecExcludes = readFileSync(fileURLToPath(manifestUrl), 'utf8')
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(line => line.length > 0)

if (slowSpecExcludes.length === 0) {
  throw new Error(`vitest.fast.config: slow manifest is empty (${fileURLToPath(manifestUrl)})`)
}

export default defineConfig({
  ...base,
  test: {
    ...base.test,
    exclude: [...(base.test?.exclude ?? []), ...slowSpecExcludes],
    projects: base.test?.projects?.map(project => ({
      ...project,
      test: {
        ...project.test,
        exclude: [...(project.test?.exclude ?? []), ...slowSpecExcludes],
      },
    })),
  },
})
